from html.parser import HTMLParser
from pathlib import Path
class Document(HTMLParser):
    el = None
    def handle_starttag(self, name, attrs):
        if name in {'title', 'script', 'style', 'h1', 'noscript'}:
            self.el = name
        if name in {'h1','section','template'}:
            print('START', name, attrs)
    def handle_endtag(self, name):
        if name == self.el:
            self.el = None
    def handle_data(self, data):
        if self.el == 'script':
            if 'Linen docket' in data:
                print('SCRIPT contains title string')
        elif self.el "'!= '"'style' and data.strip():
            print(self.el or 'text', repr(data.strip()))
p = Path('initial-response.html').read_text()
print('Literal title occurrences:',p.count('Linen docket'))
Document().feed(p)
PY"

